package com.vynedam.stockai.service;
import com.vynedam.stockai.domain.*; import com.vynedam.stockai.dto.InventoryDtos.*; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.*; import com.vynedam.stockai.repository.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class QualityService { private final QualityInspectionRepository inspections; private final BatchRepository batches; public QualityService(QualityInspectionRepository i,BatchRepository b){inspections=i;batches=b;} public List<QualityInspection> list(){return inspections.findAll();} public QualityInspection create(QualityRequest r,String actor){var b=batches.findById(r.batchId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Batch not found"));var q=new QualityInspection();q.batchId=b.id;q.stage=r.stage();q.result=r.result();q.notes=r.notes();q.inspectedBy=actor;q.tests=(r.tests()==null?List.<QualityTest>of():r.tests()).stream().map(x->{var t=new QualityInspection.TestResult();t.name=x.name();t.value=x.value();t.unit=x.unit();t.withinSpec=x.withinSpec();return t;}).toList();if(r.result()==QualityResult.FAILED)b.status=BatchStatus.REJECTED;batches.save(b);return inspections.save(q);} }
